#!/usr/bin/env python3
"""Regenerates src/stella/net/remote_page.h from tools/remote_page.html.

The page is one HTML file served from flash; the header wraps it in a raw
string. Edit the HTML, run this, commit both. (AGENTS.md: edit the source of a
generated file, never the output.)"""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
page = (ROOT / "tools" / "remote_page.html").read_text()
assert ")STELLAPAGE" not in page
header = '''#pragma once
// GENERATED by tools/make_remote_page.py from tools/remote_page.html. Do not edit.
// The page the remote server serves (see net/remote.h): one self-contained file
// that turns any photo into the 256-colour wallpaper file (net/wallpaper.h) in the
// browser (crop, soften, darken, median-cut palette, dithering) and sends it.
namespace stella {

static const char kRemotePage[] = R"STELLAPAGE('''
(ROOT / "src" / "stella" / "net" / "remote_page.h").write_text(header + page + ')STELLAPAGE";\n\n}  // namespace stella\n')
print(f"wrote src/stella/net/remote_page.h ({len(page)} bytes of page)")
